insert into site_config(key, value, updated_at) values ('banner_rotator', '{"enabled":true,"bg":"#2E6E6A","messages":[{"tr":"Günün kelimesi: **ubiquitous** — her yerde bulunan, yaygın.","en":"Word of the day: **ubiquitous** — found everywhere, very common.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **mitigate** — hafifletmek, azaltmak.","en":"Word of the day: **mitigate** — to make less severe.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **nuance** — ince anlam farkı, nüans.","en":"Word of the day: **nuance** — a subtle difference in meaning.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **coherent** — tutarlı, mantıklı akan.","en":"Word of the day: **coherent** — logical and well-connected.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **concise** — özlü, gereksiz söz içermeyen.","en":"Word of the day: **concise** — short and to the point.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **inference** — çıkarım, satır aralarını okuma.","en":"Word of the day: **inference** — a conclusion drawn from evidence.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Günün kelimesi: **arbitrary** — keyfi, gelişigüzel.","en":"Word of the day: **arbitrary** — based on chance, not reason.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **empirical** — gözleme/deneye dayalı.","en":"Word of the day: **empirical** — based on observation or experiment.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **salient** — göze çarpan, en önemli.","en":"Word of the day: **salient** — most noticeable or important.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **ambiguous** — belirsiz, birden çok anlamlı.","en":"Word of the day: **ambiguous** — open to more than one meaning.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **explicit** — açık, doğrudan belirtilen.","en":"Word of the day: **explicit** — stated clearly and directly.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **rhetoric** — etkili dil kullanımı, retorik.","en":"Word of the day: **rhetoric** — the art of persuasive language.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Günün kelimesi: **paraphrase** — başka sözcüklerle ifade etmek.","en":"Word of the day: **paraphrase** — to restate in other words.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **cohesion** — metin bütünlüğü, bağdaşıklık.","en":"Word of the day: **cohesion** — how well ideas connect in a text.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Günün kelimesi: **juxtapose** — yan yana koyup karşılaştırmak.","en":"Word of the day: **juxtapose** — to place side by side for contrast.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **plausible** — makul, akla yatkın.","en":"Word of the day: **plausible** — reasonable and believable.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **advocate** — savunmak; savunucu.","en":"Word of the day: **advocate** — to support; a supporter.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **undermine** — temelini zayıflatmak.","en":"Word of the day: **undermine** — to weaken gradually.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **prevalent** — yaygın, hâkim.","en":"Word of the day: **prevalent** — widespread, common.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **scrutinize** — dikkatle incelemek.","en":"Word of the day: **scrutinize** — to examine closely.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **compelling** — ikna edici, sürükleyici.","en":"Word of the day: **compelling** — convincing and forceful.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **redundant** — gereksiz tekrar eden.","en":"Word of the day: **redundant** — unnecessary, repetitive.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **synthesize** — parçaları birleştirip bütün kurmak.","en":"Word of the day: **synthesize** — to combine parts into a whole.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **implicit** — üstü kapalı, ima edilen.","en":"Word of the day: **implicit** — implied, not directly stated.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **feasible** — yapılabilir, uygulanabilir.","en":"Word of the day: **feasible** — possible to do easily.","link":"https://gringlizce.com/kelime"},{"tr":"İlginç bilgi: İngilizcede en çok kullanılan harf **e**''dir.","en":"Fun fact: the most common letter in English is **e**.","link":"https://gringlizce.com/blog"},{"tr":"İlginç bilgi: SAT ezber değil, **akıl yürütme** ölçer.","en":"Fun fact: the SAT tests **reasoning**, not memorization.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İlginç bilgi: IELTS bandı **0 ile 9** arasında yarım puanlarla verilir.","en":"Fun fact: IELTS is scored in half-bands from **0 to 9**.","link":"https://gringlizce.com/ielts-ornek-sorular"},{"tr":"İlginç bilgi: \"set\" sözcüğünün İngilizcede en çok anlamı vardır.","en":"Fun fact: \"set\" has more meanings than any other English word.","link":"https://gringlizce.com/kelime"},{"tr":"İlginç bilgi: TOEFL tamamen bilgisayar üzerinden ve akademik odaklıdır.","en":"Fun fact: the TOEFL is fully computer-based and academic.","link":"https://gringlizce.com/toefl-soru-bankasi"},{"tr":"İlginç bilgi: İngilizce kelimelerin yaklaşık %60''ı Latince/Fransızca kökenlidir.","en":"Fun fact: about 60% of English words have Latin or French roots.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İlginç bilgi: Digital SAT uyarlanır — ilk modül sonraki modülün zorluğunu belirler.","en":"Fun fact: the Digital SAT is adaptive — module 1 sets module 2''s difficulty.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İlginç bilgi: \"e\" harfi olmadan roman yazan yazarlar olmuştur (lipogram).","en":"Fun fact: some novels are written with no letter \"e\" — a lipogram.","link":"https://gringlizce.com/blog"},{"tr":"İlginç bilgi: IELTS''te Reading ve Listening''de **çeyrek puanlar yoktur**, sorular tek tek sayılır.","en":"Fun fact: IELTS Reading and Listening are scored by raw correct answers.","link":"https://gringlizce.com/ielts-soru-bankasi"},{"tr":"İlginç bilgi: YDS/YÖKDİL''de her sorunun ağırlığı eşittir; strateji zaman yönetimidir.","en":"Fun fact: in YDS every question counts equally — timing is the strategy.","link":"https://gringlizce.com/yds-soru-bankasi"},{"tr":"İlginç bilgi: İngilizcede yaklaşık her iki saatte bir yeni bir sözcük türetilir.","en":"Fun fact: a new English word is coined roughly every two hours.","link":"https://gringlizce.com/kelime"},{"tr":"İlginç bilgi: \"I am\" İngilizcedeki en kısa tam cümledir.","en":"Fun fact: \"I am\" is the shortest complete sentence in English.","link":"https://gringlizce.com/genel-ingilizce"},{"tr":"İlginç bilgi: Noktalama bir cümlenin anlamını tümden değiştirebilir.","en":"Fun fact: punctuation alone can flip a sentence''s meaning.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İlginç bilgi: SAT Reading''de \"en iyi\" cevap, çoğu kez en kanıtlı olandır — en uzunu değil.","en":"Fun fact: on SAT Reading the best answer is the best-supported, not the longest.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İlginç bilgi: İngilizcede sessiz harfler (silent letters) sözcüklerin ~%60''ında görülür.","en":"Fun fact: silent letters appear in around 60% of English words.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İpucu: Reading''de önce soruyu oku, sonra metne dön — zaman kazanırsın.","en":"Tip: read the question first, then scan the passage — save time.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İpucu: Kelimeyi cümle içinde öğren; yalın liste çabuk unutulur.","en":"Tip: learn words in context — plain lists fade fast.","link":"https://gringlizce.com/kelime"},{"tr":"İpucu: Yazmadan önce 2 dakika planla; yapı puanı yükseltir.","en":"Tip: plan for 2 minutes before writing — structure lifts your score.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"İpucu: IELTS yazıda 4 paragraf yeterlidir — asla 5 değil.","en":"Tip: four paragraphs is enough for IELTS writing — never five.","link":"https://gringlizce.com/ielts-ornek-sorular"},{"tr":"İpucu: Yanlışlarını bir deftere yaz; ilerlemenin en hızlı yolu budur.","en":"Tip: keep an error log — it''s the fastest way to improve.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"İpucu: Matematikte kolay soruları önce topla, zoruna sonra dön.","en":"Tip: bank the easy math questions first, return to the hard ones.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İpucu: Her gün 15 dakika okuma, haftada bir maraton çalışmadan iyidir.","en":"Tip: 15 minutes daily beats one weekend cram session.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"İpucu: Deneme çöz, ama asıl kazanç yanlışları analiz etmekte.","en":"Tip: take practice tests, but the real gain is reviewing your mistakes.","link":"https://gringlizce.com/sat-deneme"},{"tr":"İpucu: Geçiş kelimeleri (however, therefore) fikirler arası köprü kurar.","en":"Tip: transitions like ''however'' and ''therefore'' bridge your ideas.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İpucu: Konu anlatımını oku, sonra aynı konudan soru çöz — kalıcı olur.","en":"Tip: read the lesson, then solve questions on it — it sticks.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İpucu: Listening''de soruları önceden okumak seni sese hazırlar.","en":"Tip: read the questions before the audio starts — get ready to listen.","link":"https://gringlizce.com/ielts-soru-bankasi"},{"tr":"İpucu: Şık elerken \"kısmen doğru\" tuzağına dikkat et.","en":"Tip: beware the ''partly true'' trap when eliminating options.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"İpucu: Kısa ve net cümle, uzun ve karmaşık cümleden güçlüdür.","en":"Tip: a short, clear sentence beats a long, tangled one.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"İpucu: Gramer kurallarını örnek cümlelerle eşleştir, ezberleme.","en":"Tip: pair grammar rules with example sentences instead of memorizing.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İpucu: Sınav gününden önceki gece yeni konu açma; dinlen.","en":"Tip: don''t start new topics the night before — rest instead.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"İpucu: Paraphrase (yeniden ifade) IELTS ve TOEFL''da anahtar beceridir.","en":"Tip: paraphrasing is a key skill for IELTS and TOEFL.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"İpucu: UDSP için hedefin %70; zamanı bölümlere böl.","en":"Tip: UDSP needs 70% — split your time across sections.","link":"https://gringlizce.com/udsp-soru-bankasi"},{"tr":"İpucu: YDT''de kelime bilgisi belirleyicidir; her gün 10 yeni sözcük.","en":"Tip: vocabulary decides YDT — learn 10 new words a day.","link":"https://gringlizce.com/ydt-soru-bankasi"},{"tr":"İpucu: Yüksek sesle oku; telaffuz ve akıcılık birlikte gelişir.","en":"Tip: read aloud — pronunciation and fluency grow together.","link":"https://gringlizce.com/genel-ingilizce"},{"tr":"İpucu: Çeldirici uzun diye doğru sanma; kanıta bak.","en":"Tip: a long option isn''t proof — check the evidence.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Bugünkü görev: 10 soru çöz, seriyi bozma.","en":"Today''s challenge: solve 10 questions and keep your streak.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"Bugünkü görev: bir SAT Reading pasajı bitir.","en":"Today''s challenge: finish one SAT Reading passage.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Bugünkü görev: bir IELTS Task 1 yaz ve gözden geçir.","en":"Today''s challenge: write one IELTS Task 1 and review it.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"Bugünkü görev: 5 yeni kelimeyi cümle içinde kullan.","en":"Today''s challenge: use 5 new words in your own sentences.","link":"https://gringlizce.com/kelime"},{"tr":"Bugünkü görev: kısa bir deneme çöz, sonucunu not al.","en":"Today''s challenge: take a short practice test and log your score.","link":"https://gringlizce.com/toefl-denemeler"},{"tr":"Bugünkü görev: bir gramer konusunu bitir ve 5 soru çöz.","en":"Today''s challenge: finish one grammar topic and solve 5 questions.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Bugünkü görev: öğrenme haritanda bir adım ilerle.","en":"Today''s challenge: advance one step on your learning map.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Bugünkü görev: dünkü yanlışlarını tekrar çöz.","en":"Today''s challenge: redo yesterday''s wrong answers.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"Bugünkü görev: bir YDS paragraf sorusu çöz ve mantığını yaz.","en":"Today''s challenge: solve one YDS paragraph question and explain your logic.","link":"https://gringlizce.com/yds-soru-bankasi"},{"tr":"Bugünkü görev: 20 dakika sessiz, kesintisiz çalış.","en":"Today''s challenge: study 20 minutes with zero distractions.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Küçük ama düzenli adımlar, büyük sıçramalardan güçlüdür.","en":"Small, steady steps beat big, rare leaps.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Bugün çözmediğin soru, yarınki eksiğindir.","en":"The question you skip today is tomorrow''s gap.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"İlerleme hız değil, süreklilik ister.","en":"Progress rewards consistency, not speed.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Zor sorular seni değil, hazırlığını sınar.","en":"Hard questions test your prep, not your worth.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Her doğru cevap bir sonrakinin provasıdır.","en":"Every correct answer rehearses the next.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"Hedefini yaz, yolunu böl, her gün bir parça al.","en":"Write your goal, split the path, take one piece daily.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Okumadan çözme, çözmeden geçme.","en":"Don''t answer before reading, don''t move on before checking.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Bugün 1% daha iyi ol; bir yıl sonra 37 kat.","en":"Get 1% better today — that compounds over a year.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"SAT R&W: dilbilgisi soruları kısa ve net cevabı sever.","en":"SAT R&W: grammar items reward the short, clean answer.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"SAT Math: birim ve işaret hatalarını son 10 saniyede kontrol et.","en":"SAT Math: check units and signs in the last 10 seconds.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"IELTS Writing: görevi tam karşıla — soru ne soruyorsa onu yaz.","en":"IELTS Writing: fully answer the task — write what''s asked.","link":"https://gringlizce.com/ielts-ornek-sorular"},{"tr":"IELTS Speaking: fikri örnekle destekle, tek cümlede bırakma.","en":"IELTS Speaking: support ideas with examples, not one liners.","link":"https://gringlizce.com/ielts-soru-bankasi"},{"tr":"TOEFL Integrated: dinlediğini ve okuduğunu bağla.","en":"TOEFL Integrated: connect what you read to what you hear.","link":"https://gringlizce.com/toefl-soru-bankasi"},{"tr":"YÖKDİL: cümle tamamlamada anlam bütünlüğü önce gelir.","en":"YÖKDİL: in sentence completion, meaning comes first.","link":"https://gringlizce.com/yds-soru-bankasi"},{"tr":"Genel İngilizce: her hafta 4 beceriyi de dokun — denge önemli.","en":"General English: touch all four skills weekly — balance matters.","link":"https://gringlizce.com/genel-ingilizce"},{"tr":"Deneme sonrası: skoru değil, hangi konuda düştüğünü not al.","en":"After a mock: log the topic you missed, not just the score.","link":"https://gringlizce.com/sat-deneme"},{"tr":"Bir konuyu bitirince aynı konudan deneme çöz — köprü kur.","en":"Finish a topic, then test it — bridge learning to practice.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Kelime kartların birikince tekrar et; unutma eğrisini yen.","en":"Review your word cards regularly — beat the forgetting curve.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **candid** — samimi, açık sözlü.","en":"Word of the day: **candid** — honest and direct.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **diligent** — özenli, çalışkan.","en":"Word of the day: **diligent** — hard-working and careful.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **skeptical** — kuşkucu, şüpheci.","en":"Word of the day: **skeptical** — doubtful, questioning.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **vivid** — canlı, capcanlı (betimleme).","en":"Word of the day: **vivid** — bright and lifelike.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **notion** — kavram, düşünce.","en":"Word of the day: **notion** — an idea or concept.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **profound** — derin, köklü.","en":"Word of the day: **profound** — very deep or intense.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **reluctant** — isteksiz, gönülsüz.","en":"Word of the day: **reluctant** — unwilling, hesitant.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **abundant** — bol, çok sayıda.","en":"Word of the day: **abundant** — plentiful, in large amounts.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **deliberate** — kasıtlı; ölçülü.","en":"Word of the day: **deliberate** — intentional; careful.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **inevitable** — kaçınılmaz.","en":"Word of the day: **inevitable** — certain to happen.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **subtle** — ince, sezilmesi güç.","en":"Word of the day: **subtle** — delicate, not obvious.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **elaborate** — ayrıntılı; ayrıntılandırmak.","en":"Word of the day: **elaborate** — detailed; to add detail.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **contrary** — aksine, zıt.","en":"Word of the day: **contrary** — opposite, conflicting.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **valid** — geçerli, sağlam (gerekçe).","en":"Word of the day: **valid** — sound and well-founded.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **acknowledge** — kabul etmek, teslim etmek.","en":"Word of the day: **acknowledge** — to accept or admit.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **derive** — türetmek, çıkarmak.","en":"Word of the day: **derive** — to obtain from a source.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **restrain** — dizginlemek, tutmak.","en":"Word of the day: **restrain** — to hold back.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **notable** — dikkate değer, önemli.","en":"Word of the day: **notable** — worthy of attention.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **contradict** — çelişmek, yalanlamak.","en":"Word of the day: **contradict** — to state the opposite.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **emphasize** — vurgulamak.","en":"Word of the day: **emphasize** — to give special importance.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **conventional** — geleneksel, alışılmış.","en":"Word of the day: **conventional** — traditional, standard.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **transparent** — saydam; açık, anlaşılır.","en":"Word of the day: **transparent** — clear and easy to understand.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **anticipate** — öngörmek, beklemek.","en":"Word of the day: **anticipate** — to expect in advance.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **objective** — nesnel; hedef.","en":"Word of the day: **objective** — unbiased; a goal.","link":"https://gringlizce.com/kelime"},{"tr":"Günün kelimesi: **relevant** — konuyla ilgili, yerinde.","en":"Word of the day: **relevant** — closely connected to the topic.","link":"https://gringlizce.com/kelime"}]}'::jsonb, now()) on conflict (key) do update set value = excluded.value, updated_at = now();